import {configureWellCanvas,wellBrowserView,wellCanvasView,wellInspectorView,bindWellCanvas,canvasContext,addAcceptedResults,showProposal,openCanvasAction} from './well-canvas.js';
import {modules} from './catalog.js';
import {methods as localMethods} from './science-methods.js';
import {api,session,API_ORIGIN} from './auth.js';
import * as repository from './project-repository.js';
import {allowedTool} from './project-overview.js';
import {openCloudCopy} from './workspace-cloud-copy.js';

let host, loadedProject=null, loading=false, remote={configurations:[],runs:[]}, methods=localMethods;
let activeMenu=null, bindingsController, pollTimer, selectedToolRoute=null, error='', requestGeneration=0;
const previews=new Map(),results=new Map(),$=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[['sources','Sources','data',['files','wells','documents','trajectories','digitize']],['logs','Logs','logs',['logs']],['qc','QA/QC','shield',['qc']],['qualitative','Qualitative interpretation','eye',['lithology','fluids']],['quantitative','Quantitative interpretation','settings',['shale','porosity','saturation','permeability','mineralogy']],['advanced','Advanced interpretation','layers',['nmr','core','height','images','pressure','reconstruct','corrections']],['cutoffs','Cutoffs','decisions',['cutoffs']],['summaries','Reservoir summaries','reports',['summaries']],['modeling','Modeling','models',['seismic','structure','properties','rockphysics']],['engineering','Engineering','pin',['geomechanics','production','planning','simulation']],['decisions','Decisions','decisions',['volumes','opportunities','uncertainty']]];
const routes=new Set(['interpretation','qualitative','quantitative','models','decisions',...modules.filter(m=>['Interpretation','Qualitative','Quantitative','Advanced','Modeling','Engineering','Decisions'].includes(m.group)).map(m=>m.id),'trajectories']);
export const isInterpretationRoute=route=>route!=='seismic'&&routes.has(route);
export function configureInterpretation(context){host=context;configureWellCanvas({host,getProject:project,project,state,datasets,openMethod:(id,recipe)=>{const m=methods.find(m=>m.id===id);if(!m)throw new Error('This recipe method is unavailable for the current workflows.');openTool(m.tool,id);if(recipe){Object.assign(selection(),{parameters:structuredClone(recipe.parameters),notes:recipe.notes||''});for(const binding of Object.values(selection().bindings||{}))binding.confirmed=false;save();host.render();}},chooseMethod,reviewRun:id=>{const w=state().windows.find(w=>w.runId===id);if(!w)throw new Error('Open this calculation from Run history to review it.');reviewResult(w);},inspectDataset:async d=>{const tool='source-view';openTool(tool,null,false);const w=selection();if(w){w.datasetId=d.id;state().board.focus='analysis';await loadPreview(w);}else host.render();}});}
const project=()=>host.getProject();
const state=()=>{const s=host.getState();s.interpretation||={schemaVersion:1,windows:[],selected:null,browser:true,inspector:true,grid:true,annotations:[],cursor:null};return s.interpretation;};
const datasets=()=>{const stored=host.getState().ingestion?.datasets?.filter(d=>d.active!==false)||[];return [...stored,...(state().proposals||[]).filter(d=>!stored.some(a=>a.id===d.id))];};
const moduleName=id=>modules.find(m=>m.id===id)?.name||(id==='source-view'?'Source evidence':id);
const visibleMethod=m=>m.workflows.includes('either')||m.workflows.every(w=>project().workflows.includes(w));
const toolsFor=group=>group[3].filter(tool=>allowedTool(tool,project(),modules));
const selection=()=>state().windows.find(w=>w.id===state().selected);
const specFor=w=>methods.find(m=>m.id===w?.method);
const indexFactor=column=>({'m':1,'metres':1,'meters':1,'ft':.3048,'feet':.3048}[String(column?.effectiveUnit||column?.unit||'').toLowerCase()]||null);
const save=()=>host.save();

export function interpretationView(route){
 const sourceKey=session.user?.uid+':'+project().id;if(loadedProject!==sourceKey){requestGeneration++;loadedProject=sourceKey;remote={configurations:[],runs:[]};methods=localMethods;previews.clear();results.clear();selectedToolRoute=null;error='';loading=false;queueMicrotask(async()=>{await refresh();for(const w of state().windows.filter(w=>!w.closed)){if(w.tool!=='logs'&&w.datasetId&&!previews.has(w.datasetId))await loadPreview(w).catch(e=>host.toast(e.message));if(w.runId&&remote.runs.some(r=>r.id===w.runId&&['completed','accepted','rejected'].includes(r.status)))await openResult(w).catch(e=>host.toast(e.message));}});}
 if(route!==selectedToolRoute){selectedToolRoute=route;const alias={models:project().workflows.includes('seismic')?'seismic':'properties',decisions:'volumes',qualitative:'lithology',quantitative:'shale'}[route]||route;const target=modules.find(m=>m.id===alias);if(target&&routes.has(route)&&!state().windows.some(w=>w.tool===alias))openTool(alias,null,false);}
 const s=state(),w=selection();
 return `<section class="iw" aria-label="Interpretation canvas"><header class="iw-heading"><div><div class="study-kicker">INTERPRETATION STUDIO</div><h1>${esc(project().name)}</h1><p>${project().storage==='cloud'?'Cloud calculations · immutable input versions':'Local content stays on this device · Cloud copy required for calculations'}</p></div><div class="actions"><button id="iw-refresh">${host.icon('clock')}Refresh</button><button id="iw-toggle-inspector" aria-expanded="${s.inspector}">${s.inspector?'Hide':'Show'} properties</button></div></header>
 <div class="iw-ribbon" role="toolbar" aria-label="Interpretation tools">${groups.filter(g=>toolsFor(g).length).map(g=>`<div class="iw-ribbon-group"><button class="iw-icon ${activeMenu===g[0]?'active':''}" data-iw-group="${g[0]}" aria-label="${g[1]}" title="${g[1]}" aria-haspopup="menu" aria-expanded="${activeMenu===g[0]}">${host.icon(g[2])}</button><div class="iw-dropdown" data-iw-menu="${g[0]}" role="menu" ${activeMenu===g[0]?'':'hidden'}><strong>${g[1]}</strong>${toolsFor(g).map(tool=>`<div class="iw-subgroup"><button role="menuitem" data-iw-tool="${tool}" aria-haspopup="true" ${tool==='digitize'?'disabled title="Raster digitization unavailable; use a digital export"':''}>${esc(moduleName(tool))}${host.icon('chevron')}</button><div class="iw-submenu"><button role="menuitem" data-iw-tool="${tool}" ${tool==='digitize'?'disabled':''}>Open ${esc(moduleName(tool))}</button>${methods.filter(m=>m.tool===tool&&visibleMethod(m)).map(m=>`<button role="menuitem" data-iw-method="${m.id}">${esc(m.name)}</button>`).join('')}</div></div>`).join('')}</div></div>`).join('')}<span class="iw-ribbon-spacer"></span><button class="iw-icon" id="iw-toggle-browser" aria-label="Toggle project browser" title="Project browser" aria-expanded="${s.browser}">${host.icon('layers')}</button><button class="iw-icon" id="iw-grid" aria-label="Toggle canvas grid" title="Canvas grid" aria-pressed="${s.grid}">${host.icon('overview')}</button></div>
 ${error?`<div class="iw-error" role="alert">${esc(error)}</div>`:''}
 <div class="iw-body ${s.browser?'':'iw-no-browser'} ${s.inspector?'':'iw-no-inspector'}">${s.browser?wellBrowserView():''}${wellCanvasView(s.windows.filter(v=>!v.closed&&v.id===s.selected).map(windowView).join(''))}${s.inspector?(s.board?.focus==='analysis'?inspector(w):wellInspectorView()):''}</div>
 <div class="iw-bottom"><span>${datasets().length} active datasets · ${remote.runs.length} recent runs</span><button id="iw-history">Run history</button>${project().storage!=='cloud'?'<button id="iw-cloud-copy">Create Cloud copy…</button>':''}</div></section>`;
}

function browser(){const s=state();return `<aside class="iw-browser" aria-label="Project evidence"><header><strong>Project browser</strong><button class="iw-icon" id="iw-browser-close" aria-label="Collapse project browser">${host.icon('close')}</button></header><label class="iw-search"><input id="iw-source-search" placeholder="Find well or dataset…" aria-label="Find well or dataset"></label><div class="iw-evidence-list">${datasets().map(d=>`<button data-iw-source="${esc(d.id)}"><strong>${esc(d.name)}</strong><small>${esc(d.well||'Unassigned')} · ${Number(d.rowCount||0).toLocaleString()} records</small><small>${esc(d.status||'Imported')} · ${esc(d.family)}</small></button>`).join('')||'<p>No active datasets. Add and review source data first.</p>'}</div><button class="iw-add-source" id="iw-add-source">${host.icon('plus')}Add data</button><h3>Canvas views</h3><div class="iw-view-list">${s.windows.map(w=>`<button data-iw-window="${w.id}">${host.icon(w.closed?'eye':'logs')}<span>${esc(moduleName(w.tool))}<small>${esc(specFor(w)?.name||'Evidence view')}</small></span></button>`).join('')||'<p>No views open.</p>'}</div></aside>`;}

function windowView(w,index){
 const s=state(),preview=previews.get(w.datasetId),result=results.get(w.runId),spec=specFor(w);
 let body;
 if(w.tool==='logs'&&preview){body=logView(w,preview);}
 else if(result){body=resultView(w,result);}
 else if(preview){body=tableView(preview);}
 else body=`<div class="iw-window-empty">${host.icon(w.tool==='seismic'?'models':'logs')}<h3>${esc(spec?.name||moduleName(w.tool))}</h3><p>${w.datasetId?'Open the input preview or configure a calculation in Properties.':'Select imported evidence in Properties to begin.'}</p>${w.datasetId?`<button data-iw-load="${w.id}">Open evidence</button>`:''}</div>`;
 return `<article class="iw-window ${s.selected===w.id?'iw-selected':''}" data-iw-frame="${w.id}" style="left:${w.x??24+index*28}px;top:${w.y??24+index*32}px;width:${w.width||560}px;height:${w.height||450}px;z-index:${s.selected===w.id?20:2+index}"><header data-iw-drag="${w.id}"><span>${host.icon(w.tool==='logs'?'logs':'layers')}<strong>${esc(moduleName(w.tool))}</strong><small>${esc(spec?.name||'Evidence view')}</small></span><button class="iw-icon" data-iw-close="${w.id}" aria-label="Close ${esc(moduleName(w.tool))}">${host.icon('close')}</button></header><div class="iw-window-body">${body}</div><footer><span>${esc(w.runId?remote.runs.find(r=>r.id===w.runId)?.status||'Saved result':w.datasetId?datasets().find(d=>d.id===w.datasetId)?.well||'Source preview':'Configuration')}</span>${w.tool==='logs'&&preview?`<button data-iw-export="${w.id}">Export SVG</button>`:''}<button data-iw-select="${w.id}">Properties</button></footer><button class="iw-resize" data-iw-resize="${w.id}" aria-label="Resize canvas view"></button></article>`;
}

function numeric(v){return typeof v==='number'&&Number.isFinite(v);}
function extent(values){const v=values.filter(numeric);if(!v.length)return null;let lo=Math.min(...v),hi=Math.max(...v);if(lo===hi){lo-=.5;hi+=.5;}return[lo,hi];}
function logView(w,preview){
 const columns=preview.columns||[],rows=preview.rows||[],depthIndex=Math.max(0,columns.findIndex(c=>c.id===(w.depthColumn||columns[0]?.id))),curveIds=w.curves?.length?w.curves:columns.slice(1,4).filter(c=>rows.some(r=>numeric(r[columns.indexOf(c)]))).map(c=>c.id);
 const factor=indexFactor(columns[depthIndex]),depth=rows.map(r=>numeric(r[depthIndex])?r[depthIndex]*(factor||1):null),dr=extent(depth);if(!dr)return '<p class="iw-message">Select a numeric depth/index column.</p>';
 const top=w.top!==undefined&&w.top!==''?Number(w.top):dr[0],base=w.base!==undefined&&w.base!==''?Number(w.base):dr[1];if(!(base>top))return '<p class="iw-message">Depth base must exceed top.</p>';
 const width=600,height=340,py=d=>30+(d-top)/(base-top)*270,trackW=500/Math.max(1,curveIds.length),paths=[];
 const offset=Number(w.flattenOffset||0),marker=factor?state().cursor:null;
 const tracks=curveIds.slice(0,12).map((id,i)=>{const ci=columns.findIndex(c=>c.id===id);if(ci<0)return '';const c=columns[ci],settings=w.axes?.[id]||{},values=rows.map(r=>settings.log&&numeric(r[ci])?(r[ci]>0?Math.log10(r[ci]):null):r[ci]),range=extent(values);if(!range)return '';let [lo,hi]=range;const px=v=>70+i*trackW+(settings.reverse?1-(v-lo)/(hi-lo):(v-lo)/(hi-lo))*(trackW-16);let d='',previous=false;for(let j=0;j<rows.length;j++){const z=depth[j]-offset,v=values[j];if(!numeric(z)||!numeric(v)||z<top||z>base){previous=false;continue;}d+=(previous?'L':'M')+px(v).toFixed(2)+','+py(z).toFixed(2);previous=true;}paths.push(d);return `<g><rect x="${62+i*trackW}" y="26" width="${trackW}" height="278" fill="none" stroke="#dce7e4"/><text x="${70+i*trackW}" y="13">${esc(c.mnemonic)}</text><text x="${70+i*trackW}" y="24" class="iw-chart-unit">${esc(c.effectiveUnit||c.unit||'unit unconfirmed')}${settings.log?' · log':''}</text><path d="${d}" fill="none" stroke="${['#087c73','#b78540','#527ea1','#965e83'][i%4]}" stroke-width="1.1"/></g>`;}).join('');
 return `<div class="iw-plot-notice">${rows.length.toLocaleString()} displayed / ${preview.rowCount.toLocaleString()} source rows · source index ${esc(columns[depthIndex]?.effectiveUnit||columns[depthIndex]?.unit||'unit unconfirmed')} · ${esc(preview.references?.depthReference||'depth reference unconfirmed')}</div><svg class="iw-log-chart" data-iw-chart="${w.id}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Actual stored log curves"><rect width="600" height="340" fill="white"/>${Array.from({length:6},(_,i)=>{const d=top+(base-top)*i/5;return `<g><line x1="60" x2="570" y1="${py(d)}" y2="${py(d)}" stroke="#ecf1ef"/><text x="4" y="${py(d)+3}">${d.toFixed(1)}</text></g>`;}).join('')}${tracks}${state().annotations.filter(x=>factor&&x.kind==='marker'&&numeric(x.depth)).map(x=>`<g><line x1="60" x2="570" y1="${py(x.depth)}" y2="${py(x.depth)}" stroke="#b78540" stroke-dasharray="3 3"/><text x="470" y="${py(x.depth)-4}">${esc(x.label)}</text></g>`).join('')}${numeric(marker)&&marker>=top&&marker<=base?`<line x1="60" x2="570" y1="${py(marker)}" y2="${py(marker)}" stroke="#314a46" stroke-dasharray="2 2"/>`:''}</svg>`;
}
function tableView(preview){return `<div class="iw-plot-notice">Stored evidence · ${preview.rows.length} displayed / ${preview.rowCount} rows</div><div class="iw-table"><table><thead><tr>${preview.columns.slice(0,20).map(c=>`<th>${esc(c.mnemonic)}<small>${esc(c.effectiveUnit||c.unit||'unconfirmed')}</small></th>`).join('')}</tr></thead><tbody>${preview.rows.slice(0,100).map(row=>`<tr>${row.slice(0,20).map(v=>`<td>${esc(Array.isArray(v)?'['+v.length+' samples]':v===null?'—':numeric(v)?Number(v.toPrecision(7)):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function linePlot(series){
 const entries=Object.entries(series).filter(([,v])=>Array.isArray(v)&&v.some(numeric)).slice(0,4);if(!entries.length)return '';
 return `<svg viewBox="0 0 600 230" class="iw-result-chart" role="img" aria-label="Computed result preview">${entries.map(([key,v],i)=>{const r=extent(v);let previous=false,d='';v.slice(0,2000).forEach((value,j)=>{if(!numeric(value)){previous=false;return;}d+=(previous?'L':'M')+(20+j/Math.max(1,v.length-1)*560).toFixed(2)+','+(200-(value-r[0])/(r[1]-r[0])*155).toFixed(2);previous=true;});return `<path d="${d}" fill="none" stroke="${['#087c73','#b78540','#527ea1','#965e83'][i]}" stroke-width="1.2"/><text x="${20+i*140}" y="18">${esc(key)}</text>`;}).join('')}</svg>`;
}
function arrayPlot(array){if(!array?.length||!Array.isArray(array[0]))return '';const rows=array.slice(0,128),cols=Math.min(256,rows[0].length),range=extent(rows.flat());if(!range)return '';return `<svg viewBox="0 0 ${cols} ${rows.length}" class="iw-array-chart" role="img" aria-label="Actual array values; bounded preview">${rows.map((row,y)=>row.slice(0,cols).map((v,x)=>{const t=numeric(v)?Math.max(0,Math.min(1,(v-range[0])/(range[1]-range[0]))):.5;return `<rect x="${x}" y="${y}" width="1" height="1" fill="rgb(${Math.round(245-t*225)},${Math.round(248-t*118)},${Math.round(247-t*125)})"/>`;}).join('')).join('')}</svg>`;}
function resultView(w,r){const array=Object.values(r.preview||{}).find(v=>Array.isArray(v?.[0]));return `<div class="iw-result-summary"><strong>${esc(methods.find(m=>m.id===r.method)?.name||r.method)}</strong><small>${esc(r.previewNotice)} · Not scientifically approved</small></div>${r.datasets?.some(d=>d.indexColumnId)?`<button data-iw-proposal="${esc(w.runId)}">Compare full proposed curves on canvas</button>`:""}${array?arrayPlot(array):linePlot(r.preview||{})}<dl class="iw-metrics">${Object.entries(r.summary||{}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd></div>`).join('')}</dl>${(r.warnings||[]).map(v=>`<p class="iw-warning">${esc(v)}</p>`).join('')}<details><summary>Method and provenance</summary><p>${esc(r.methodVersion)}</p><a href="${esc(r.reference)}" target="_blank" rel="noopener">Method reference</a><pre>${esc(JSON.stringify(r.provenance,null,2))}</pre></details>`;}

function inspector(w){
 if(!w)return '<aside class="iw-inspector"><header><strong>Properties</strong></header><div class="iw-inspector-empty">Select a canvas view to configure its inputs and review results.</div></aside>';
 const spec=specFor(w),available=methods.filter(m=>m.tool===w.tool&&visibleMethod(m)),ds=datasets().find(d=>d.id===w.datasetId),run=remote.runs.find(r=>r.id===w.runId),preview=previews.get(w.datasetId);
 return `<aside class="iw-inspector" aria-label="Tool properties"><header><strong>${esc(moduleName(w.tool))}</strong><button class="iw-icon" id="iw-inspector-close" aria-label="Collapse properties">${host.icon('close')}</button></header><form id="iw-properties"><label class="field">Method<select name="method">${available.length?available.map(m=>`<option value="${m.id}" ${m.id===w.method?'selected':''}>${esc(m.name)}</option>`).join(''):'<option value="">Evidence and annotations</option>'}</select></label><label class="field">Evidence dataset<select name="datasetId"><option value="">Select a dataset</option>${datasets().map(d=>`<option value="${esc(d.id)}" ${w.datasetId===d.id?'selected':''}>${esc(d.well?d.well+' · ':'')}${esc(d.name)}</option>`).join('')}</select></label>${w.datasetId?'<button id="iw-load-evidence" type="button">Open stored evidence</button>':''}
 ${w.tool==='logs'&&ds?logControls(w,ds,preview):''}
 ${spec?`<p class="iw-method-description">${esc(spec.description||'Inputs retain their source identity. Confirm mapping, units and applicability before running.')}</p><details open><summary>Input mapping and units</summary>${spec.inputs.map(i=>{const b=w.bindings?.[i.role]||{},source=datasets().find(d=>d.id===(b.datasetId||w.datasetId));return `<fieldset class="iw-binding"><legend>${esc(i.role)} · ${esc(i.dimension)}</legend><select name="binding:${i.role}:datasetId" aria-label="${esc(i.role)} dataset"><option value="">Select dataset</option>${datasets().map(d=>`<option value="${esc(d.id)}" ${source?.id===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select name="binding:${i.role}:columnId" aria-label="${esc(i.role)} column"><option value="">Select column</option>${(source?.columns||[]).filter(c=>!source.activeColumns||source.activeColumns.includes(c.id)).map(c=>`<option value="${esc(c.id)}" ${b.columnId===c.id?'selected':''}>${esc(c.mnemonic)} · ${esc(c.effectiveUnit||c.unit||'unit unknown')} · ${esc(c.id)}</option>`).join('')}</select><input name="binding:${i.role}:unit" aria-label="${esc(i.role)} confirmed unit" placeholder="Confirmed unit" value="${esc(b.unit||'')}"><label class="iw-check"><input type="checkbox" name="binding:${i.role}:confirmed" ${b.confirmed?'checked':''}>I confirm this mapping and unit</label></fieldset>`;}).join('')}${spec.inputs.length>1?`<label class="iw-check"><input type="checkbox" name="alignmentConfirmed" ${w.alignmentConfirmed?'checked':''}>Different datasets have explicitly aligned rows</label>`:''}</details><details open><summary>Method parameters</summary>${Object.entries(spec.parameters).map(([key,p])=>`<label class="field">${esc(key)}<small>${esc(p.description)}</small>${p.type==='json'?`<textarea name="parameter:${key}" rows="3">${esc(JSON.stringify(w.parameters?.[key]??p.default,null,2))}</textarea>`:p.type==='boolean'?`<input type="checkbox" name="parameter:${key}" ${(w.parameters?.[key]??p.default)?'checked':''}>`:`<input name="parameter:${key}" ${p.type==='number'?'type="number" step="any"':''} value="${esc(w.parameters?.[key]??p.default??'')}">`}</label>`).join('')||'<p>No additional scalar parameters.</p>'}</details>`:''}
 ${w.scope?`<label class="iw-check"><input type="checkbox" name="useCanvasScope" checked>Use selected canvas index${w.scope.top!==undefined?' / interval':''}${w.scope.rowRanges?' / brushed source rows':''}</label><p class="iw-method-description">Index: ${esc(w.scope.reference)} · ${esc(w.scope.unit)}. Source rows are retained without resampling.</p>`:''}<label class="field">Interpretation notes<textarea name="notes" rows="3">${esc(w.notes||'')}</textarea></label><div class="iw-form-actions"><button type="submit">Save configuration</button>${spec?`<button type="button" id="iw-run" class="primary" ${project().storage!=='cloud'||['queued','running','cancelling'].includes(run?.status)?'disabled':''}>${run&&['queued','running','cancelling'].includes(run.status)?esc(run.status):'Validate & run'}</button>`:''}</div><p id="iw-form-message" role="status"></p>${project().storage!=='cloud'?'<p class="iw-warning">Server calculations require an explicit Cloud copy. Viewing local evidence does not upload files.</p>':''}</form>
 ${run?`<section class="iw-run-state"><strong>${esc(run.status)}${run.stale?' · stale inputs':''}</strong><p>${esc(run.message||'')}</p>${['queued','running'].includes(run.status)?'<button id="iw-cancel-run">Cancel calculation</button>':''}${['completed','accepted','rejected'].includes(run.status)?`<button id="iw-open-result">Open result</button>${run.status==='completed'?'<button id="iw-review-result">Review result…</button>':''}`:''}</section>`:''}
 <details class="iw-annotations"><summary>Markers, picks and reviewer notes</summary><button id="iw-add-annotation">Add interpretation…</button>${state().annotations.filter(a=>a.tool===w.tool||a.kind==='marker').map(a=>`<div><strong>${esc(a.label)}</strong><p>${esc(a.kind)} ${a.depth!==undefined?esc(a.depth)+' m':''}</p><button data-iw-remove-annotation="${a.id}">Remove</button></div>`).join('')}</details><details><summary>Method boundaries</summary><p>No vendor-specific inversion, automatic fluid determination, complex faulted-grid generation or simulation execution is implied.</p>${spec?`<a href="${esc(spec.reference)}" target="_blank" rel="noopener">Read method reference</a>`:''}</details></aside>`;
}
function logControls(w,ds,preview){const cols=preview?.columns||ds.columns||[];return `<details open><summary>Track display</summary><label class="field">Depth/index column<select name="depthColumn">${cols.map(c=>`<option value="${c.id}" ${w.depthColumn===c.id?'selected':''}>${esc(c.mnemonic)} · ${esc(c.effectiveUnit||c.unit||'unconfirmed')}</option>`).join('')}</select></label>${cols.map(c=>`<div class="iw-track-setting"><label><input type="checkbox" name="curve" value="${c.id}" ${(w.curves||cols.slice(1,4).map(v=>v.id)).includes(c.id)?'checked':''}>${esc(c.mnemonic)}</label><label><input type="checkbox" name="log:${c.id}" ${w.axes?.[c.id]?.log?'checked':''}>Log</label><label><input type="checkbox" name="reverse:${c.id}" ${w.axes?.[c.id]?.reverse?'checked':''}>Reverse</label></div>`).join('')}<label class="field">Display top (metres when depth unit is known)<input name="top" type="number" step="any" value="${esc(w.top??'')}"></label><label class="field">Display base (metres when depth unit is known)<input name="base" type="number" step="any" value="${esc(w.base??'')}"></label><label class="field">Flatten offset (metres when depth unit is known)<input name="flattenOffset" type="number" step="any" value="${esc(w.flattenOffset||0)}"></label><label class="field">Preview start row<input name="startRow" type="number" min="0" max="249999" step="1" value="${w.startRow||0}"></label></details>`;}

function openTool(tool,methodId=null,redraw=true){
 if(tool==='files'){host.openImporter();return;}
 if(tool==='wells'){openCanvasAction('register');return;}
 if(tool==='digitize'){host.toast('Raster log digitization is not implemented. Import a digital LAS/CSV export.');return;}
 if(tool==='logs'){if(state().board)state().board.focus='logs';if(redraw)host.render();return;}
 let linked=null;try{linked=canvasContext();}catch(error){host.toast(error.message);return;}

 const target=tool==='trajectories'?'planning':tool;
 const spec=methods.find(m=>m.id===methodId)||methods.find(m=>m.tool===target&&visibleMethod(m));
 const existing=state().windows.findLast(v=>v.tool===target&&v.method===(spec?.id||'')&&(!linked||v.datasetId===linked.dataset.id));if(existing){existing.closed=false;state().selected=existing.id;if(state().board)state().board.focus='analysis';state().inspector=true;save();if(redraw)host.render();return;}const s=state(),w={id:crypto.randomUUID(),tool:target,method:spec?.id||'',parameters:{},bindings:{},x:24+(s.windows.length%4)*24,y:24+(s.windows.length%4)*28,width:560,height:450};if(linked&&spec){w.datasetId=linked.dataset.id;w.scope=spec.inputs.length&&!['seismic','structure','properties','planning','simulation'].includes(spec.tool)?linked.scope:null;w.bindings=suggestBindings(spec,linked);}s.windows.push(w);if(s.board)s.board.focus='analysis';s.selected=w.id;s.inspector=true;save();if(redraw)host.render();
}
async function refresh(){
 const p=project(),generation=requestGeneration;if(!p||loading)return;loading=true;
 try{if(p.storage==='cloud'){const [caps,records,data]=await Promise.all([api(`/api/projects/${p.id}/science/capabilities`),api(`/api/projects/${p.id}/science`),api(`/api/projects/${p.id}/imports`)]);if(generation!==requestGeneration||p.id!==project()?.id)return;methods=caps.methods;remote=records;host.getState().ingestion=data;}error='';}
 catch(e){if(generation===requestGeneration)error=e.message;}
 finally{if(generation===requestGeneration){loading=false;if(isInterpretationRoute(location.hash.slice(1)))host.render();schedulePoll();}}
}
function schedulePoll(){clearTimeout(pollTimer);if(remote.runs.some(r=>['queued','running','cancelling'].includes(r.status)))pollTimer=setTimeout(async()=>{if(!isInterpretationRoute(location.hash.slice(1)))return;try{const active=remote.runs.filter(r=>['queued','running','cancelling'].includes(r.status));for(const r of active)await api(`/api/projects/${project().id}/science/runs/${r.id}`);await refresh();}catch(e){host.toast(e.message);}},4000);}

async function loadPreview(w){
 const p=project(),dataset=datasets().find(d=>d.id===w.datasetId);if(!dataset)throw new Error('Select an active imported dataset.');
 const generation=requestGeneration;let result;
 if(p.storage==='cloud')result=await api(`/api/projects/${p.id}/science/datasets/${dataset.id}/rows?start=${Number(w.startRow)||0}&limit=2000`);
 else{const importRecord=host.getState().ingestion?.imports?.find(i=>i.id===dataset.importId);const full=importRecord?.datasets?.find(d=>d.id===dataset.id)||dataset;const rows=[];let offset=0,start=Number(w.startRow)||0;for(const chunk of full.chunks||[]){if(offset+chunk.rows<=start){offset+=chunk.rows;continue;}const blob=await repository.getArtifact(p,dataset.importId,chunk.name);const text=chunk.name.endsWith('.gz')?await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text():await blob.text();if(text.length>32*1024**2)throw new Error('Select a smaller local preview.');for(const line of text.trim().split('\n')){if(offset++>=start)rows.push(JSON.parse(line));if(rows.length>=2000)break;}if(rows.length>=2000)break;}result={columns:full.columns,rows,rowCount:full.rowCount,references:full.references||dataset.references||{},metadata:full.metadata||{},well:full.well};}
 if(generation!==requestGeneration)return;previews.set(w.datasetId,result);host.render();
}
function collect(current,form){
 const w=structuredClone(current);
 const previous=JSON.stringify({method:w.method,bindings:w.bindings,parameters:w.parameters,scope:w.scope});
 const data=new FormData(form);if(!data.has('useCanvasScope'))w.scope=null;const spec=methods.find(m=>m.id===data.get('method'));w.method=spec?.id||'';w.datasetId=data.get('datasetId');w.parameters={};w.bindings={};w.alignmentConfirmed=data.has('alignmentConfirmed');w.notes=String(data.get('notes')||'');
 for(const item of spec?.inputs||[]){const prefix='binding:'+item.role+':';w.bindings[item.role]={datasetId:String(data.get(prefix+'datasetId')||w.datasetId||''),columnId:String(data.get(prefix+'columnId')||''),unit:String(data.get(prefix+'unit')||'').trim(),confirmed:data.has(prefix+'confirmed')};}
 for(const [key,p]of Object.entries(spec?.parameters||{})){const value=data.get('parameter:'+key);w.parameters[key]=p.type==='json'?JSON.parse(value||'null'):p.type==='number'?value===''?null:Number(value):p.type==='boolean'?data.has('parameter:'+key):String(value||'');}
 if(w.tool==='logs'){w.depthColumn=data.get('depthColumn');w.curves=data.getAll('curve');w.axes={};for(const c of datasets().find(d=>d.id===w.datasetId)?.columns||[])w.axes[c.id]={log:data.has('log:'+c.id),reverse:data.has('reverse:'+c.id)};for(const key of ['top','base','flattenOffset','startRow'])w[key]=data.get(key)||'';}
 if(previous!==JSON.stringify({method:w.method,bindings:w.bindings,parameters:w.parameters,scope:w.scope})){delete w.runId;}
 Object.assign(current,w);delete current.pendingParameters;save();
}
function configBody(w){return {revision:w.configurationRevision||0,method:w.method,bindings:w.bindings||{},parameters:w.parameters||{},alignmentConfirmed:!!w.alignmentConfirmed,notes:w.notes||'',scope:w.scope||null};}
async function saveConfiguration(w){
 if(project().storage!=='cloud')return;
 w.configurationId||=crypto.randomUUID();const result=await api(`/api/projects/${project().id}/science/configurations/${w.configurationId}`,{method:'PUT',body:configBody(w)});w.configurationRevision=result.revision;save();
}
async function runCalculation(w){
 if(project().storage!=='cloud')throw new Error('Create a Cloud copy before running server calculations.');
 await host.flush();await api(`/api/projects/${project().id}/science/validate`,{method:'POST',body:configBody(w)});await saveConfiguration(w);
 const run=await api(`/api/projects/${project().id}/science/runs`,{method:'POST',body:{configurationId:w.configurationId,revision:w.configurationRevision,idempotencyKey:crypto.randomUUID()}});w.runId=run.id;remote.runs.unshift(run);save();await host.flush();host.render();schedulePoll();
}
async function openResult(w){if(!w.runId)return;const value=await api(`/api/projects/${project().id}/science/runs/${w.runId}/result`);results.set(w.runId,value);host.render();}
function addAnnotation(w){host.modal('Record interpretation',`<form id="iw-annotation-form"><label class="field">Type<select name="kind"><option value="note">Reviewer note</option><option value="marker">Formation marker</option><option value="interval">Facies / completion interval</option><option value="horizon">Horizon picks</option><option value="fault">Fault picks</option><option value="contact">Contact interpretation</option><option value="case">Simulation handoff case</option></select></label><label class="field">Name / interpretation<input name="label" required maxlength="120"></label><label class="field">Depth (metres, if applicable)<input name="depth" type="number" step="any"></label><label class="field">Geometry / interval / case metadata (JSON)<textarea name="geometry" rows="4">{}</textarea></label><label class="field">Reference and evidence<textarea name="evidence" required maxlength="2000"></textarea></label><p id="iw-annotation-error" role="alert"></p><button class="primary">Save interpretation</button></form>`);$('#iw-annotation-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),g=JSON.parse(f.get('geometry')||'{}');if(typeof g!=='object'||!g)throw new Error('Enter an object or array for geometry.');const depth=f.get('depth');state().annotations.push({id:crypto.randomUUID(),tool:w.tool,kind:f.get('kind'),label:f.get('label'),...(depth!==''?{depth:Number(depth)}:{}),geometry:g,evidence:f.get('evidence'),datasetId:w.datasetId||null,createdAt:new Date().toISOString()});save();$('#dialog').close();host.render();}catch(e){$('#iw-annotation-error').textContent=e.message;}};}
function reviewResult(w){const run=remote.runs.find(r=>r.id===w.runId);host.modal('Review calculated result',`<p>Acceptance activates independent result datasets. Originals remain unchanged. Acceptance records your decision; it is not automatic scientific approval.</p><form id="iw-review-form"><label class="field">Decision<select name="decision"><option value="accept">Accept as a new version</option><option value="reject">Reject proposal</option></select></label><label class="field">Review comment<textarea name="comment" required maxlength="4000"></textarea></label><label class="iw-check"><input type="checkbox" name="reviewed" required>I reviewed method applicability, inputs, units and warnings.</label><p id="iw-review-error" role="alert"></p><button class="primary">Record review</button></form>`);$('#iw-review-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target);await api(`/api/projects/${project().id}/science/runs/${run.id}/review`,{method:'POST',body:{revision:run.revision,decision:f.get('decision'),comment:f.get('comment')}});$('#dialog').close();await refresh();if(f.get('decision')==='accept')addAcceptedResults(run.id);else {for(const d of state().proposals||[])if(d.scientificRunId===run.id)d.status='Rejected · comparison only';save();host.render();}}catch(e){$('#iw-review-error').textContent=e.message;b.disabled=false;}};}
function history(){host.modal('Calculation history',`<div class="iw-history">${remote.runs.map(r=>`<button data-iw-history-run="${r.id}"><strong>${esc(methods.find(m=>m.id===r.method)?.name||r.method)}</strong><span>${esc(r.status)}${r.stale?' · stale inputs':''}</span><small>${esc(new Date(r.createdAt).toLocaleString())}</small></button>`).join('')||'<p>No calculations have run in this project.</p>'}</div>`);document.querySelectorAll('[data-iw-history-run]').forEach(b=>b.onclick=async()=>{const r=remote.runs.find(v=>v.id===b.dataset.iwHistoryRun);openTool(methods.find(m=>m.id===r.method)?.tool,r.method,false);const w=selection();w.runId=r.id;w.configurationId=r.configurationId;w.configurationRevision=r.configurationRevision;Object.assign(w,{parameters:r.configuration.parameters,bindings:r.configuration.bindings,alignmentConfirmed:r.configuration.alignmentConfirmed,notes:r.configuration.notes,scope:r.configuration.scope||null});save();$('#dialog').close();if(['completed','accepted','rejected'].includes(r.status))try{await openResult(w);}catch(e){host.toast(e.message);}host.render();});}

export function bindInterpretation(){
 const root=$('.iw');if(!root)return;bindWellCanvas();bindingsController?.abort();bindingsController=new AbortController();const signal=bindingsController.signal;
 const safe=fn=>async e=>{try{await fn(e);}catch(error){host.toast(error.message);}};
 const toggle=key=>{state()[key]=!state()[key];save();host.render();};
 $('#iw-toggle-inspector').onclick=()=>toggle('inspector');$('#iw-inspector-close')?.addEventListener('click',()=>toggle('inspector'));$('#iw-toggle-browser').onclick=()=>toggle('browser');$('#iw-browser-close')?.addEventListener('click',()=>toggle('browser'));$('#iw-grid').onclick=()=>toggle('grid');$('#iw-refresh').onclick=()=>refresh();$('#iw-add-source')?.addEventListener('click',()=>host.openImporter());$('#iw-history').onclick=history;$('#iw-cloud-copy')?.addEventListener('click',()=>cloudCopy());
 function menu(id){activeMenu=id;root.querySelectorAll('[data-iw-menu]').forEach(m=>m.hidden=m.dataset.iwMenu!==id);root.querySelectorAll('[data-iw-group]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.iwGroup===id)));}
 root.querySelectorAll('[data-iw-group]').forEach(b=>{b.onclick=()=>menu(activeMenu===b.dataset.iwGroup?null:b.dataset.iwGroup);b.onpointerenter=e=>{if(e.pointerType==='mouse')menu(b.dataset.iwGroup);};b.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();menu(b.dataset.iwGroup);root.querySelector(`[data-iw-menu="${b.dataset.iwGroup}"] button`)?.focus();}};});
 root.querySelectorAll('[data-iw-tool]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(b.parentElement.classList.contains('iw-subgroup')){b.parentElement.classList.toggle('iw-sub-open');return;}activeMenu=null;openTool(b.dataset.iwTool);});root.querySelectorAll('[data-iw-method]').forEach(b=>b.onclick=e=>{e.stopPropagation();activeMenu=null;const m=methods.find(m=>m.id===b.dataset.iwMethod);openTool(m.tool,m.id);});
 root.querySelectorAll('.iw-subgroup > button').forEach(b=>b.onkeydown=e=>{if(e.key==='ArrowRight'){e.preventDefault();b.parentElement.classList.add('iw-sub-open');b.nextElementSibling.querySelector('button')?.focus();}});
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.iw-ribbon'))menu(null);},{signal});
 root.addEventListener('keydown',e=>{if(e.key==='Escape'){const group=activeMenu;menu(null);root.querySelector(`[data-iw-group="${group}"]`)?.focus();}if(e.target.closest('.iw-dropdown')&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){const list=[...e.target.closest('[role=menu]').querySelectorAll('button')].filter(b=>b.getClientRects().length);const i=list.indexOf(e.target);e.preventDefault();list[e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length]?.focus();}},{signal});
 root.querySelectorAll('[data-iw-window]').forEach(b=>b.onclick=()=>{const s=state(),w=s.windows.find(w=>w.id===b.dataset.iwWindow);w.closed=false;s.selected=w.id;s.inspector=true;save();host.render();});
 root.querySelectorAll('[data-iw-frame]').forEach(frame=>frame.onpointerdown=e=>{if(e.target.closest('button,input,select,textarea')||state().selected===frame.dataset.iwFrame)return;state().selected=frame.dataset.iwFrame;save();});
 root.querySelectorAll('[data-iw-close]').forEach(b=>b.onclick=()=>{state().windows.find(w=>w.id===b.dataset.iwClose).closed=true;if(state().board)state().board.focus='logs';save();host.render();});root.querySelectorAll('[data-iw-select]').forEach(b=>b.onclick=()=>{state().selected=b.dataset.iwSelect;state().inspector=true;save();host.render();});
 root.querySelectorAll('[data-iw-source]').forEach(b=>b.onclick=safe(async()=>{let w=selection();if(!w){openTool('logs',null,false);w=selection();}w.datasetId=b.dataset.iwSource;w.bindings={};save();await loadPreview(w);}));
 $('#iw-source-search')?.addEventListener('input',e=>{root.querySelectorAll('[data-iw-source]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
 root.querySelectorAll('[data-iw-load]').forEach(b=>b.onclick=safe(()=>loadPreview(state().windows.find(w=>w.id===b.dataset.iwLoad))));
 const form=$('#iw-properties'),w=selection();if(form&&w){if(w.pendingParameters)for(const input of form.querySelectorAll('[name^="parameter:"],textarea[name=notes]')){const value=w.pendingParameters[input.name];if(value!==undefined&&input.type!=='checkbox')input.value=value;}
  form.addEventListener('input',()=>{try{const oldRun=w.runId;collect(w,form);if(oldRun&&!w.runId){const status=root.querySelector('.iw-run-state');if(status)status.innerHTML='<p>Draft changed. The previous result remains in Run history; calculate again for these inputs.</p>';const body=root.querySelector(`[data-iw-frame="${w.id}"] .iw-window-body`);if(body)body.innerHTML='<div class="iw-window-empty"><h3>Configuration changed</h3><p>Run this method again to calculate results for the edited inputs.</p></div>';}}catch{w.pendingParameters=Object.fromEntries(new FormData(form));save();}});
  form.onsubmit=safe(async e=>{e.preventDefault();collect(w,form);if(w.method)await saveConfiguration(w);await host.flush();host.toast(project().storage==='portable'?'Draft updated. Download the project to retain changes.':'Configuration saved to the selected project destination.');host.render();});
  form.elements.method.onchange=()=>{const id=form.elements.method.value;w.method=id;w.parameters={};w.bindings={};w.configurationId=null;w.configurationRevision=0;delete w.runId;delete w.pendingParameters;save();host.render();};
  form.elements.datasetId.onchange=()=>{w.datasetId=form.elements.datasetId.value;w.bindings={};w.scope=null;save();host.render();};
  form.querySelectorAll('[name^="binding:"]').forEach(input=>{if(input.name.endsWith(':datasetId'))input.onchange=()=>{try{collect(w,form);host.render();}catch(e){host.toast(e.message);}};if(input.name.endsWith(':columnId'))input.onchange=()=>{const role=input.name.split(':')[1],dsId=form.elements.namedItem('binding:'+role+':datasetId').value,ds=datasets().find(d=>d.id===dsId),c=ds?.columns.find(c=>c.id===input.value);form.elements.namedItem('binding:'+role+':unit').value=c?.effectiveUnit||c?.unit||'';form.elements.namedItem('binding:'+role+':confirmed').checked=false;};});
  $('#iw-load-evidence')?.addEventListener('click',safe(async()=>{collect(w,form);await loadPreview(w);}));$('#iw-run')?.addEventListener('click',safe(async e=>{e.target.disabled=true;try{collect(w,form);await runCalculation(w);}finally{if(e.target.isConnected)e.target.disabled=false;}}));
  $('#iw-open-result')?.addEventListener('click',safe(()=>openResult(w)));$('#iw-review-result')?.addEventListener('click',()=>reviewResult(w));$('#iw-cancel-run')?.addEventListener('click',safe(async()=>{await api(`/api/projects/${project().id}/science/runs/${w.runId}/cancel`,{method:'POST',body:{}});await refresh();}));$('#iw-add-annotation')?.addEventListener('click',()=>addAnnotation(w));
 }
 root.querySelectorAll('[data-iw-proposal]').forEach(b=>b.onclick=safe(()=>showProposal(b.dataset.iwProposal,results.get(b.dataset.iwProposal))));
 root.querySelectorAll('[data-iw-remove-annotation]').forEach(b=>b.onclick=()=>{state().annotations=state().annotations.filter(a=>a.id!==b.dataset.iwRemoveAnnotation);save();host.render();});
 root.querySelectorAll('[data-iw-export]').forEach(b=>b.onclick=()=>{const svg=root.querySelector(`[data-iw-chart="${b.dataset.iwExport}"]`);if(svg)host.download('StrataX-log-view.svg',new Blob(['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 340">'+svg.innerHTML+'</svg>'],{type:'image/svg+xml'}));});
 for(const handle of root.querySelectorAll('[data-iw-drag],[data-iw-resize]'))handle.onpointerdown=e=>{if(e.target.closest('button')&&!handle.dataset.iwResize)return;e.preventDefault();const id=handle.dataset.iwDrag||handle.dataset.iwResize,w=state().windows.find(v=>v.id===id),frame=handle.closest('.iw-window'),canvas=$('#iw-canvas'),r=canvas.getBoundingClientRect(),x=e.clientX,y=e.clientY,origin={x:w.x||0,y:w.y||0,width:frame.offsetWidth,height:frame.offsetHeight};state().selected=id;handle.setPointerCapture(e.pointerId);const move=event=>{if(handle.dataset.iwResize){w.width=Math.max(280,Math.min(r.width-(w.x||0),origin.width+event.clientX-x));w.height=Math.max(240,Math.min(r.height-(w.y||0),origin.height+event.clientY-y));frame.style.width=w.width+'px';frame.style.height=w.height+'px';}else{w.x=Math.max(0,Math.min(Math.max(0,r.width-frame.offsetWidth),origin.x+event.clientX-x));w.y=Math.max(0,Math.min(Math.max(0,r.height-frame.offsetHeight),origin.y+event.clientY-y));frame.style.left=w.x+'px';frame.style.top=w.y+'px';}};const up=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',up);handle.removeEventListener('pointercancel',up);save();host.render();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);handle.addEventListener('pointercancel',up);};
 root.querySelectorAll('[data-iw-chart]').forEach(chart=>chart.onclick=e=>{const w=state().windows.find(v=>v.id===chart.dataset.iwChart),p=previews.get(w.datasetId);const r=chart.getBoundingClientRect(),depthColumn=p.columns.findIndex(c=>c.id===(w.depthColumn||p.columns[0]?.id)),range=extent(p.rows.map(row=>row[Math.max(0,depthColumn)]));if(!range)return;const factor=indexFactor(p.columns[Math.max(0,depthColumn)]);if(!factor){host.toast('Confirm a recognized depth unit before linking cursors.');return;}const top=w.top!==undefined&&w.top!==''?Number(w.top):range[0]*factor,base=w.base!==undefined&&w.base!==''?Number(w.base):range[1]*factor;state().cursor=top+Math.max(0,Math.min(1,((e.clientY-r.top)/r.height*340-30)/270))*(base-top);save();host.render();});
}

function cloudCopy(){return openCloudCopy(host,'interpretation');}

function suggestBindings(spec,linked){const roles={depth:['DEPT','DEPTH','MD','TVD','TVDSS'],md:['DEPT','DEPTH','MD'],gr:['GR','GAM','GAMMA'],density:['RHOB','DEN','RHOZ'],neutron:['NPHI','TNPH'],slowness:['DT','DTC','AC'],porosity:['PHI','PHIT','PHIE'],total:['PHIT','PHI'],vsh:['VSH','VCL'],rt:['RT','ILD','RDEP','LLD'],sw:['SW'],k:['K','PERM'],inclination:['INC','INCL'],azimuth:['AZ','AZI']};const bindings={};for(const input of spec.inputs){let column=null;if(['curve','x','core','response'].includes(input.role))column=linked.dataset.columns.find(c=>c.id===linked.curve?.columnId);else if(['depth','md'].includes(input.role))column=linked.dataset.columns.find(c=>c.id===linked.scope?.columnId);else {const matches=linked.dataset.columns.filter(c=>(roles[input.role]||[]).includes(c.mnemonic.toUpperCase()));if(matches.length===1)column=matches[0];}bindings[input.role]={datasetId:linked.dataset.id,columnId:column?.id||'',unit:column?.effectiveUnit||column?.unit||'',confirmed:false};}return bindings;}
function chooseMethod(){host.modal('Calculate from canvas selection',`<p>Choose a supported method. Suggested mappings and units must still be confirmed before processing.</p><div class="wb-method-picker">${methods.filter(visibleMethod).filter(m=>m.tool!=='logs').map(m=>`<button data-wb-method-choice="${m.id}"><strong>${esc(m.name)}</strong><small>${esc(moduleName(m.tool))}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-wb-method-choice]').forEach(b=>b.onclick=()=>{const m=methods.find(m=>m.id===b.dataset.wbMethodChoice);$('#dialog').close();openTool(m.tool,m.id);});}
